JS='''
document.querySelectorAll('[data-reader-section]').forEach(a=>a.addEventListener('click',ev=>{ev.preventDefault();locate('reader','reader-'+a.dataset.readerSection)}));
document.querySelectorAll('[data-paper]').forEach(b=>b.addEventListener('click',()=>locate('library','paper-'+b.dataset.paper)));
document.querySelectorAll('[data-reader-view]').forEach(b=>b.addEventListener('click',()=>{switchView(b.dataset.readerView);history.replaceState(null,'','#view-'+b.dataset.readerView);document.getElementById(b.dataset.readerView+'-view').scrollIntoView({behavior:'instant'})}));
'''
